<?php
require_once __DIR__ . '/../includes/bootstrap.php'; require_login();
$uid=(int)$_SESSION['user_id']; $q=db()->prepare('SELECT COUNT(*) FROM documents WHERE user_id=?');$q->execute([$uid]);$docCount=(int)$q->fetchColumn();
$recent=db()->prepare('SELECT id,original_name,category,uploaded_at,file_size FROM documents WHERE user_id=? ORDER BY uploaded_at DESC LIMIT 5');$recent->execute([$uid]);$docs=$recent->fetchAll();
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Dashboard | LegacyVault</title><link rel="stylesheet" href="../css/style.css"></head><body class="app-page"><aside class="sidebar"><a class="brand side-brand" href="dashboard.php"><span class="brand-icon">▣</span> LegacyVault</a><nav class="side-nav"><a class="active" href="dashboard.php">⌂ <span>Dashboard</span></a><a href="documents.php">▤ <span>Documents</span></a><a href="logout.php">↪ <span>Logout</span></a></nav></aside><main class="app-main"><header class="app-header"><div><h1>Dashboard</h1><p>Your digital legacy, organized securely.</p></div><div class="user-chip">Welcome, <strong><?=e($_SESSION['user_name'] ?? 'User')?></strong><span class="avatar"><?=e(strtoupper(substr($_SESSION['user_name'] ?? 'U',0,1)))?></span></div></header><section class="stats-grid" style="grid-template-columns:repeat(auto-fit,minmax(180px,1fr))"><div class="stat-card"><span class="stat-icon purple">▤</span><div><small>Your Documents</small><strong><?=$docCount?></strong></div></div><div class="stat-card"><span class="stat-icon blue">♢</span><div><small>Vault Security</small><strong>Email OTP</strong></div></div></section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Recent Documents</h2><a href="documents.php">Open vault</a></div><?php if (!$docs): ?><p style="font-size:13px;color:#737792">Your vault is empty. Upload your first document to get started.</p><?php else: ?><table><thead><tr><th>File Name</th><th>Category</th><th>Uploaded</th><th>Size</th></tr></thead><tbody><?php foreach($docs as $d): ?><tr><td><?=e($d['original_name'])?></td><td><?=e($d['category'])?></td><td><?=e(date('d M Y',strtotime($d['uploaded_at'])))?></td><td><?=e(number_format($d['file_size']/1024,1))?> KB</td></tr><?php endforeach; ?></tbody></table><?php endif; ?><a class="btn btn-primary" style="margin-top:16px" href="documents.php">Open Secure Document Vault</a></section></main></body></html>
